"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7675],{54392:e=>{e.exports=JSON.parse('{"functions":[{"name":"run","desc":"Invokes `callback(context)`, waiting at most `timeout` seconds.","params":[{"name":"callback","desc":"","lua_type":"(any) -> any"},{"name":"context","desc":"","lua_type":"any"},{"name":"timeout","desc":"","lua_type":"number"},{"name":"services","desc":"`monotonic`, `sleep` and `spawn`.","lua_type":"any"}],"returns":[{"desc":"`ok` with the return value, or a reason of `FinalizerError` or `FinalizerTimeout`.","lua_type":"Outcome"}],"function_type":"static","source":{"line":39,"path":"src/internal/Finalizer.luau"}}],"properties":[],"types":[],"name":"Finalizer","desc":"Runs the `finalize` hook under a deadline.\\n\\nThe hook is expected to yield, so it runs on its own thread while the caller\\nwaits for completion or the deadline, whichever comes first. The spawner and\\nclock are injected, which lets tests drive the timeout path without real time\\npassing.\\n\\n:::caution\\nA timed-out hook is abandoned, not cancelled. Luau cannot interrupt a thread\\nblocked in a web call, so a `finalize` that times out during\\n`ReserveServerAsync` still completes later and still allocates a server.\\nMuster has stopped waiting and aborted the match. Write hooks whose side\\neffects are idempotent or cheap to abandon, and release expensive ones in\\n`onAbort`.\\n:::","source":{"line":22,"path":"src/internal/Finalizer.luau"}}')}}]);